{
  "root_causes": [
    {
      "service": "cart",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT (SELECT count(*) FROM normal_traces WHERE service_name='cart') AS cart_spans_normal, (SELECT count(*) FROM abnormal_traces WHERE service_name='cart') AS cart_spans_abnormal, (SELECT count(*) FROM abnormal_traces WHERE span_name LIKE 'grpc.oteldemo.CartService%' AND attr_status_code='Error') AS failed_cart_client_calls",
          "claim": "Cart emitted 448 spans in the normal window and zero in the abnormal window; 106 cart client calls failed."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'norm' p, avg(value) rss_avg FROM normal_metrics WHERE attr_k8s_pod_name='cart-d45f557f7-6nj9t' AND metric='container.memory.rss' UNION ALL SELECT 'abn', avg(value) FROM abnormal_metrics WHERE attr_k8s_pod_name='cart-d45f557f7-6nj9t' AND metric='container.memory.rss'",
          "claim": "Cart pod RSS fell from about 40.5 MB normal to about 0.3 MB abnormal, consistent with the process being down or restarted and idle."
        },
        {
          "kind": "metric",
          "sql": "SELECT CAST(time AS VARCHAR) t, attr_k8s_pod_name pod, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name='cart-d45f557f7-6nj9t' ORDER BY time",
          "claim": "Cart container restart counter reads 1 from the start of the abnormal window, versus 0 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE span_name IN ('tcp.connect') OR span_name LIKE 'grpc.oteldemo.CartService%' OR span_name LIKE 'oteldemo.CartService%' GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Frontend and checkout cart calls fail in about 0.04 to 0.4 ms, and frontend tcp.connect spans error out, so cart is unreachable."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "cart",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND attr_status_code='Error' GROUP BY ALL",
          "claim": "Checkout's GetCart client calls to cart all error (22 of 22), and PlaceOrder server spans error in the same pattern."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY ALL",
          "claim": "Frontend's CheckoutService/PlaceOrder client calls and POST /api/checkout server spans all return errors, with 500 status."
        }
      ]
    },
    {
      "from": "cart",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.CartService/AddItem','grpc.oteldemo.CartService/GetCart','POST /api/cart','GET /api/cart') GROUP BY ALL",
          "claim": "Frontend cart calls and /api/cart server spans fail with 500 in about 100% of cases in the abnormal window."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code sc, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name IN ('ingress','router frontend egress') GROUP BY ALL",
          "claim": "Frontend-proxy ingress and router-frontend-egress spans return 500 for 156 requests, matching the frontend errors."
        }
      ]
    }
  ]
}
